mapper.select:
select e.event_id, e.fence_id, f.name as fence_name, e.location_id, e.user_id, e.session_id, e.node_id, e.device_code, e.mac, e.event_type, e.event_time, l.latitude, l.longitude from t_geofence_event e left join t_geofence f on f.fence_id = e.fence_id left join t_client_location l on l.id = e.location_id
and e.fence_id = #{fenceId}
and e.user_id = #{userId}
and e.session_id = #{sessionId}
and e.mac = #{mac}
and e.event_type = #{eventType}
and e.event_time >= #{startTime}
and e.event_time <= #{endTime}
order by e.event_time desc, e.event_id desc
